public class PreparedStatementRendererTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static String renderOrThrow(String sql, Object[] params) {
        try {
            return PreparedStatementRenderer.render(sql, params);
        } catch (IllegalArgumentException e) {
            return "IllegalArgumentException";
        } catch (RuntimeException e) {
            return e.getClass().getSimpleName();
        }
    }

    public static void main(String[] args) {
        try {
            check("two plain placeholders", 2,
                    PreparedStatementRenderer.placeholderCount("WHERE a = ? AND b = ?"));
            check("a question mark inside a literal is not a placeholder", 0,
                    PreparedStatementRenderer.placeholderCount("WHERE note = 'what? really'"));
            check("literals and placeholders mixed", 1,
                    PreparedStatementRenderer.placeholderCount("WHERE note = 'ok?' AND id = ?"));
            check("no placeholders at all", 0,
                    PreparedStatementRenderer.placeholderCount("SELECT 1"));

            check("a number and a quoted string",
                    "SELECT * FROM t WHERE a = 5 AND b = 'O''Brien'",
                    renderOrThrow("SELECT * FROM t WHERE a = ? AND b = ?",
                            new Object[] {Integer.valueOf(5), "O'Brien"}));
            check("null becomes NULL, not a quoted word",
                    "UPDATE t SET note = NULL WHERE id = 3",
                    renderOrThrow("UPDATE t SET note = ? WHERE id = ?",
                            new Object[] {null, Integer.valueOf(3)}));
            check("a boolean is not quoted",
                    "UPDATE t SET active = true",
                    renderOrThrow("UPDATE t SET active = ?", new Object[] {Boolean.TRUE}));
            check("a question mark in a literal is left alone",
                    "SELECT * FROM t WHERE note = 'ok?' AND id = 9",
                    renderOrThrow("SELECT * FROM t WHERE note = 'ok?' AND id = ?",
                            new Object[] {Integer.valueOf(9)}));
            check("a statement with no placeholders is unchanged",
                    "SELECT 1", renderOrThrow("SELECT 1", new Object[] {}));
            check("a null params array means zero parameters",
                    "SELECT 1", renderOrThrow("SELECT 1", null));

            check("too few parameters is rejected", "IllegalArgumentException",
                    renderOrThrow("WHERE a = ? AND b = ?", new Object[] {Integer.valueOf(1)}));
            check("too many parameters is rejected", "IllegalArgumentException",
                    renderOrThrow("WHERE a = ?",
                            new Object[] {Integer.valueOf(1), Integer.valueOf(2)}));
        } catch (RuntimeException e) {
            System.out.println("FAIL  unexpected exception -- " + e);
            failures++;
        }

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

