/**
 * TASK: Render a prepared statement with its parameters filled in.
 *
 * This is a DEBUGGING tool -- it shows what a PreparedStatement would run.
 * Real code always sends the ? placeholders and the values separately.
 *
 * placeholderCount(sql) counts the ? characters that are really placeholders.
 *   A ? inside a single-quoted SQL literal is ordinary text, not a placeholder:
 *     "WHERE a = ? AND b = ?"            -> 2
 *     "WHERE note = 'what? really' "     -> 0
 *     "WHERE note = 'ok?' AND id = ?"    -> 1
 *   Inside a literal, two single quotes in a row ('') are an escaped quote.
 *
 * render(sql, params) replaces each placeholder, in order, with its value:
 *     null            -> NULL
 *     Number/Boolean  -> its toString, unquoted           123, true
 *     anything else   -> single-quoted, with every ' doubled
 *                        O'Brien -> 'O''Brien'
 *   render("SELECT * FROM t WHERE a = ? AND b = ?", new Object[] {5, "O'Brien"})
 *       -> "SELECT * FROM t WHERE a = 5 AND b = 'O''Brien'"
 *
 *   If params has a different length than placeholderCount(sql), throw
 *   new IllegalArgumentException("expected N parameters"). A null params array
 *   counts as length 0.
 */
public class PreparedStatementRenderer {

    public static int placeholderCount(String sql) {
        int count = 0;
        boolean inLiteral = false;
        for (int i = 0; i < sql.length(); i++) {
            char c = sql.charAt(i);
            if (c == '\'') {
                inLiteral = !inLiteral;
            } else if (c == '?' && !inLiteral) {
                count++;
            }
        }
        return count;
    }

    private static String literal(Object value) {
        if (value == null) {
            return "NULL";
        }
        if (value instanceof Number || value instanceof Boolean) {
            return value.toString();
        }
        return "'" + value.toString().replace("'", "''") + "'";
    }

    public static String render(String sql, Object[] params) {
        Object[] values = (params == null) ? new Object[0] : params;
        int expected = placeholderCount(sql);
        if (values.length != expected) {
            throw new IllegalArgumentException("expected " + expected + " parameters");
        }

        StringBuilder out = new StringBuilder();
        boolean inLiteral = false;
        int next = 0;
        for (int i = 0; i < sql.length(); i++) {
            char c = sql.charAt(i);
            if (c == '\'') {
                inLiteral = !inLiteral;
                out.append(c);
            } else if (c == '?' && !inLiteral) {
                out.append(literal(values[next]));
                next++;
            } else {
                out.append(c);
            }
        }
        return out.toString();
    }
}
